def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length == 0:
        return float('inf')  # can't move if step length is zero and d != 0
    if d == length:
        return 1
    if d < length:
        # One jump can overshoot and come back; so 2 jumps suffice
        return 2
    # Otherwise, at least ceil(d/length) jumps
    return math.ceil(d / length)

