        return True

    n = len(arr)
    # Check if already sorted
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Try all right shifts
    # Right shift by k means arr[-k:] + arr[:-k]
    for k in range(1, n):
